BEGIN;

DROP TABLE IF EXISTS foods CASCADE;

CREATE TABLE foods (
    "Id" uuid NOT NULL,
    "NameVi" text NOT NULL,
    "NameEn" text NULL,
    "Category" text NULL,
    "Description" text NULL,
    "CaloriesKcal" numeric NULL,
    "ProteinG" numeric NULL,
    "CarbsG" numeric NULL,
    "FatG" numeric NULL,
    "FiberG" numeric NULL,
    "EstimatedPriceVnd" integer NULL,
    "DefaultServingG" integer NOT NULL,
    "ImageUrl" text NULL,
    "IsActive" boolean NULL,
    "CreatedAt" timestamp with time zone NULL,
    "Region" text NULL,
    "PreparationMinutes" integer NULL,
    "CookingMinutes" integer NULL,
    "DifficultyLevel" text NULL,
    "MealType" text NULL,
    "DietType" text NULL,
    "MainIngredient" text NULL,
    "CookingMethod" text NULL,
    CONSTRAINT "PK_foods" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_foods_DefaultServingG_Positive" CHECK ("DefaultServingG" > 0)
);

INSERT INTO foods ("Id", "NameVi", "NameEn", "Category", "Description", "CaloriesKcal", "ProteinG", "CarbsG", "FatG", "FiberG", "EstimatedPriceVnd", "DefaultServingG", "ImageUrl", "IsActive", "CreatedAt", "Region")
