    "Description" = EXCLUDED."Description", "CaloriesKcal" = EXCLUDED."CaloriesKcal",
    "ProteinG" = EXCLUDED."ProteinG", "CarbsG" = EXCLUDED."CarbsG",
    "FatG" = EXCLUDED."FatG", "EstimatedPriceVnd" = EXCLUDED."EstimatedPriceVnd",
    "PreparationMinutes" = EXCLUDED."PreparationMinutes", "CookingMinutes" = EXCLUDED."CookingMinutes",
    "DifficultyLevel" = EXCLUDED."DifficultyLevel", "MealType" = EXCLUDED."MealType",
    "DietType" = EXCLUDED."DietType", "MainIngredient" = EXCLUDED."MainIngredient",
    "CookingMethod" = EXCLUDED."CookingMethod", "IsActive" = true;
-- END GENERATED MNMN CATALOG

-- Fill missing catalog artwork with representative Unsplash-licensed images.
-- Existing/custom images are preserved; matching is based on dish category/name.
UPDATE foods
SET "ImageUrl" = CASE
    WHEN lower("NameVi") LIKE ANY (ARRAY['%cà phê%', '%trà %', '%trà sữa%', '%sinh tố%', '%smoothie%', '%nước ép%', '%nước chanh%'])
        OR "Category" = 'Thức uống'
        THEN 'https://images.unsplash.com/photo-1553530666-ba11a7da3888?w=400'
    WHEN "Category" = 'Tráng miệng'
        OR lower("NameVi") LIKE ANY (ARRAY['%chè %', '%bánh flan%', '%sữa chua%', '%yaourt%', '%kem %'])
        THEN 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=400'
    WHEN "Category" = 'Salad'
        OR lower("NameVi") LIKE ANY (ARRAY['%salad%', '%gỏi %', '%nộm %', '% trộn%'])
        THEN 'https://images.unsplash.com/photo-1540420773420-3366772f4999?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%canh %', '%súp %', '%cháo %', '%lẩu %'])
        OR "Category" = 'Món canh'
        THEN 'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%phở %', '%bún %', '%hủ tiếu%', '%mì %', '%miến %', '%cao lầu%'])
        OR "Category" = 'Món nước'
        THEN 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%cá %', '%tôm %', '%mực %', '%sò %', '%ốc %', '%cua %', '%hải sản%'])
        THEN 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%gà %', '%ức gà%', '%cánh gà%', '%đùi gà%', '%vịt %'])
        THEN 'https://images.unsplash.com/photo-1604503468506-a8da13d82791?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%bò %', '%bê %', '%thịt bò%'])
        THEN 'https://images.unsplash.com/photo-1544025162-d76694265947?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%heo %', '%thịt heo%', '%sườn %', '%thịt kho%', '%giò %'])
        THEN 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%cơm %', '%cơm chiên%', '%cơm rang%'])
        THEN 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?w=400'
    WHEN lower("NameVi") LIKE '%bánh mì%'
        THEN 'https://images.unsplash.com/photo-1509722747041-616f39b57569?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%trứng %', '%ốp la%', '%omelette%'])
        THEN 'https://images.unsplash.com/photo-1525351484163-7529414344d8?w=400'
    WHEN lower("NameVi") LIKE ANY (ARRAY['%bánh %', '%xôi %', '%há cảo%', '%hoành thánh%'])
        OR "Category" IN ('Snack', 'Món sáng')
        THEN 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=400'
    WHEN "Category" IN ('Món chay', 'Món rau củ', 'Chay')
        OR lower("NameVi") LIKE ANY (ARRAY['%rau %', '%nấm %', '%đậu hũ%', '%đậu phụ%'])
        THEN 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=400'
    ELSE 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=400'
END
WHERE "ImageUrl" IS NULL OR btrim("ImageUrl") = '';

COMMIT;
